3	import java.time.LocalDate;
4	
5	import jakarta.validation.ConstraintValidator;
6	import jakarta.validation.ConstraintValidatorContext;
7	
8	public class PetAgeValidator implements ConstraintValidator<PetAgeValidation, LocalDate> {
9	
10	    @Override
11	    public boolean isValid(LocalDate birthDate, ConstraintValidatorContext context) {
12	
13	        if (birthDate == null) {
14	            return true; 
15	        }
16	
17	        LocalDate today = LocalDate.now();
18	
19	        if (birthDate.isAfter(today)) {
20	            context.disableDefaultConstraintViolation();
21	            context.buildConstraintViolationWithTemplate(
22	                "Birth date cannot be in the future"
23	            ).addConstraintViolation();
24	            return false;
25	        }
26	
27	        if (birthDate.isBefore(today.minusYears(50))) {
28	            context.disableDefaultConstraintViolation();
29	            context.buildConstraintViolationWithTemplate(
30	                "Birth date cannot be older than 50 years"
31	            ).addConstraintViolation();
32	            return false;
33	        }
34	
35	        return true;
36	    }
37	}

